#!/usr/bin/env bash
# Builds kit/ from this machine's own Python standard library (PSF License, see THIRD_PARTY_NOTICES.md):
# pure-Python modules copied under new names, one bug planted in each, then normalised through ast.unparse
# so that diffing against the installed standard library does not locate the bug. Patch points were checked
# against CPython 3.11, 3.12 and 3.13; a patch that does not apply stops the build. Generated by
# bench/build_multifix.py.
set -eu
python3 - <<'PY'
import ast, json, os, sysconfig
BUGS = json.loads(r"""[["textwrap.py", "wrap", "            space_left = width - cur_len\n", "            space_left = width - cur_len - 1\n"], ["_pydecimal.py", "dec", "                (prec == 0 or self._int[prec-1] in '02468'):\n", "                (prec == 0 or self._int[prec-1] in '13579'):\n"], ["difflib.py", "diffs", "    beginning = start + 1     # lines start numbering with one\n    length = stop - start\n    if length == 1:\n        return '{}'.format(beginning)\n    if not length:\n        beginning -= 1        # empty ranges begin at line just before the range\n    return '{},{}'.format(beginning, length)\n", "    beginning = start\n    length = stop - start\n    if length == 1:\n        return '{}'.format(beginning)\n    if not length:\n        beginning -= 1        # empty ranges begin at line just before the range\n    return '{},{}'.format(beginning, length)\n"], ["urllib/parse.py", "urls", "    if base_parts[-1] != '':\n", "    if base_parts[-1] == '':\n"], ["statistics.py", "stats", "    if method == 'exclusive':\n        m = ld + 1\n", "    if method == 'exclusive':\n        m = ld\n"], ["argparse.py", "cli", "            if action.option_strings:\n                value = action.const\n            else:\n                value = action.default\n", "            if action.option_strings:\n                value = action.default\n            else:\n                value = action.const\n"], ["fractions.py", "ratio", "            elif floor % 2 == 0:\n", "            elif floor % 2 == 1:\n"], ["pprint.py", "pretty", "    return _safe_key(t[0]), _safe_key(t[1])\n", "    return _safe_key(t[1]), _safe_key(t[0])\n"], ["shlex.py", "lexer", "        self.escapedquotes = '\"'\n", "        self.escapedquotes = \"'\"\n"], ["plistlib.py", "plist", "    order = ('year', 'month', 'day', 'hour', 'minute', 'second')\n", "    order = ('year', 'day', 'month', 'hour', 'minute', 'second')\n"], ["calendar.py", "cal", "        day1, ndays = monthrange(year, month)\n        days_before = (day1 - self.firstweekday) % 7\n        yield from repeat(0, days_before)\n", "        day1, ndays = monthrange(year, month)\n        days_before = (self.firstweekday - day1) % 7\n        yield from repeat(0, days_before)\n"], ["fnmatch.py", "globs", "                    if stuff[0] == '!':\n                        stuff = '^' + stuff[1:]\n", "                    if stuff[0] == '!':\n                        stuff = stuff[1:]\n"], ["ipaddress.py", "netaddr", "                    (last_int - first_int + 1).bit_length() - 1)\n", "                    (last_int - first_int + 1).bit_length())\n"], ["heapq.py", "heap", "        _heapify(h)\n        while len(h) > 1:\n            try:\n                while True:\n                    value, order, next = s = h[0]\n", "        _heapify(h)\n        while len(h) > 2:\n            try:\n                while True:\n                    value, order, next = s = h[0]\n"], ["configparser.py", "config", "                        opt = parser.optionxform(path[0])\n                        v = map[opt]\n", "                        opt = path[0]\n                        v = map[opt]\n"], ["graphlib.py", "graph", "                if successor_info.npredecessors == 0:\n", "                if successor_info.npredecessors == 1:\n"]]""")
lib = sysconfig.get_paths()['stdlib']
for src, mod, old, new in BUGS:
    s = open(os.path.join(lib, src), encoding="utf-8").read()
    if s.count(old) != 1:
        raise SystemExit("gen.sh: patch point for %s not found in %s" % (mod, lib))
    open(os.path.join("kit", mod + ".py"), "w", encoding="utf-8").write(ast.unparse(ast.parse(s.replace(old, new))) + "\n")
PY
